* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    background-color: #f5f5f5;
    color: #333;
}

.container {
    padding: 30px;
    max-width: 1600px;
    margin: 0 auto;
}

h1 {
    text-align: center;
    margin-bottom: 30px;
    color: #2c3e50;
    font-size: 28px;
}

.content {
    display: flex;
    gap: 30px;
    background: white;
    padding: 20px;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}

.chart-section {
    flex: 1;
    min-width: 500px;
}

.chart-section h2 {
    font-size: 18px;
    margin-bottom: 15px;
    color: #34495e;
}

#bubble-chart {
    width: 100%;
    height: 600px;
    border: 1px solid #ddd;
    border-radius: 4px;
    background: #fafafa;
}

#legend {
    margin-top: 20px;
    padding: 15px;
    background: #f9f9f9;
    border-radius: 4px;
    display: flex;
    flex-wrap: wrap;
    gap: 15px;
}

.legend-item {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 13px;
}

.legend-color {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    border: 1px solid #ccc;
}

.table-section {
    flex: 1;
    min-width: 400px;
    display: flex;
    flex-direction: column;
}

.table-section h2 {
    font-size: 18px;
    margin-bottom: 15px;
    color: #34495e;
}

#table-container {
    flex: 1;
    overflow-y: auto;
    border: 1px solid #ddd;
    border-radius: 4px;
}

#stocks-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
}

#stocks-table thead {
    position: sticky;
    top: 0;
    background: #34495e;
    color: white;
}

#stocks-table th {
    padding: 12px 8px;
    text-align: left;
    font-weight: 600;
    border-bottom: 2px solid #2c3e50;
}

#stocks-table td {
    padding: 10px 8px;
    border-bottom: 1px solid #eee;
}

#stocks-table tbody tr {
    cursor: pointer;
    transition: background-color 0.2s ease;
}

#stocks-table tbody tr:hover {
    background-color: #f0f0f0;
}

#stocks-table tbody tr.highlighted {
    background-color: #fff3cd;
    font-weight: 600;
}

.tooltip {
    position: absolute;
    padding: 10px 12px;
    background: rgba(0, 0, 0, 0.85);
    color: white;
    border-radius: 4px;
    font-size: 13px;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.2s ease;
    z-index: 1000;
    white-space: nowrap;
    box-shadow: 0 2px 6px rgba(0,0,0,0.15);
}

.tooltip.visible {
    opacity: 1;
}

/* Bubble chart styling */
.bubble {
    stroke: white;
    stroke-width: 2px;
    cursor: pointer;
    transition: filter 0.2s ease, stroke-width 0.2s ease;
}

.bubble:hover {
    filter: brightness(1.1);
    stroke-width: 3px;
}

.bubble.highlighted {
    stroke-width: 4px;
    filter: brightness(1.15);
}

.bubble-label {
    pointer-events: none;
    text-anchor: middle;
    dominant-baseline: middle;
    font-weight: bold;
    font-size: 12px;
    fill: white;
    text-shadow: 0 1px 2px rgba(0,0,0,0.3);
}

@media (max-width: 1200px) {
    .content {
        flex-direction: column;
    }

    .chart-section,
    .table-section {
        min-width: unset;
    }
}

