// Color palette for sectors
const sectorColors = {
    'Information Technology': '#1f77b4',
    'Financials': '#ff7f0e',
    'Energy': '#2ca02c',
    'Industrials': '#d62728',
    'Health Care': '#9467bd',
    'Consumer Discretionary': '#8c564b',
    'Consumer Staples': '#e377c2',
    'Utilities': '#7f7f7f',
    'Real Estate': '#bcbd22',
    'Materials': '#17becf',
    'Communication Services': '#aec7e8',
    'ETF': '#ffbb78',
    'Other': '#c5b0d5'
};

let stockData = [];
let selectedTicker = null;

async function loadData() {
    try {
        const response = await fetch('data/stock-descriptions.csv');
        const text = await response.text();
        const lines = text.trim().split('\n');

        // Parse CSV
        const headers = lines[0].split(',');

        for (let i = 1; i < lines.length; i++) {
            const line = lines[i];
            // Handle quoted fields that might contain commas
            const fields = parseCSVLine(line);

            const stock = {
                ticker: fields[1] ? fields[1].trim() : '',
                sector: fields[2] ? fields[2].trim() : 'Other',
                name: fields[3] ? fields[3].trim().replace(/^"(.*)"$/, '$1') : '',
                marketCap: parseFloat(fields[4]) || 0,
                country: fields[7] ? fields[7].trim() : '',
                website: fields[8] ? fields[8].trim() : ''
            };

            if (stock.ticker) {
                stockData.push(stock);
            }
        }

        console.log('Loaded', stockData.length, 'stocks');

        // Initialize visualizations
        initBubbleChart();
        initTable();

    } catch (error) {
        console.error('Error loading data:', error);
    }
}

function parseCSVLine(line) {
    const result = [];
    let current = '';
    let insideQuotes = false;

    for (let i = 0; i < line.length; i++) {
        const char = line[i];
        const nextChar = line[i + 1];

        if (char === '"') {
            if (insideQuotes && nextChar === '"') {
                current += '"';
                i++;
            } else {
                insideQuotes = !insideQuotes;
            }
        } else if (char === ',' && !insideQuotes) {
            result.push(current);
            current = '';
        } else {
            current += char;
        }
    }

    result.push(current);
    return result;
}

function initBubbleChart() {
    const container = document.getElementById('bubble-chart');
    const width = container.clientWidth;
    const height = container.clientHeight;

    // Create SVG
    const svg = d3.select(container)
        .append('svg')
        .attr('width', width)
        .attr('height', height);

    // Add background
    svg.append('rect')
        .attr('width', width)
        .attr('height', height)
        .attr('fill', '#fafafa');

    // Create group for bubbles
    const bubbleGroup = svg.append('g');

    // Prepare data - exclude ETFs and entries without proper data
    const bubbleData = stockData.filter(d => {
        return d.marketCap > 0 || d.country === '';  // Include regular stocks and ETFs
    }).map(d => ({
        ...d,
        radius: d.marketCap > 0 ? Math.sqrt(d.marketCap / 1e12) * 40 : 25  // ETFs get uniform size
    }));

    // Calculate sector centers
    const sectorCenters = {};
    const sectors = [...new Set(bubbleData.map(d => d.sector))];
    sectors.forEach((sector, i) => {
        const angle = (i / sectors.length) * Math.PI * 2;
        sectorCenters[sector] = {
            x: width / 2 + Math.cos(angle) * width * 0.3,
            y: height / 2 + Math.sin(angle) * height * 0.3
        };
    });

    // Create force simulation
    const simulation = d3.forceSimulation(bubbleData)
        .force('x', d3.forceX(d => sectorCenters[d.sector].x).strength(0.05))
        .force('y', d3.forceY(d => sectorCenters[d.sector].y).strength(0.05))
        .force('collide', d3.forceCollide(d => d.radius + 2))
        .force('charge', d3.forceManyBody().strength(-30));

    // Create bubble elements
    const circles = bubbleGroup.selectAll('circle')
        .data(bubbleData, d => d.ticker)
        .join('circle')
        .attr('class', 'bubble')
        .attr('r', d => d.radius)
        .attr('fill', d => sectorColors[d.sector] || sectorColors['Other'])
        .attr('cx', d => d.x || width / 2)
        .attr('cy', d => d.y || height / 2);

    // Add labels
    const labels = bubbleGroup.selectAll('text')
        .data(bubbleData, d => d.ticker)
        .join('text')
        .attr('class', 'bubble-label')
        .attr('x', d => d.x || width / 2)
        .attr('y', d => d.y || height / 2)
        .text(d => d.ticker)
        .attr('font-size', d => Math.max(10, Math.min(16, d.radius / 3)));

    // Add interactivity
    circles
        .on('mouseenter', function(event, d) {
            if (d.marketCap === 0) return; // Skip tooltips for ETFs

            const tooltip = document.getElementById('tooltip');
            tooltip.innerHTML = `
                <strong>${d.ticker}</strong><br/>
                ${d.name}<br/>
                ${d.sector}
            `;
            tooltip.classList.add('visible');

            const [x, y] = d3.pointer(event);
            tooltip.style.left = (x + 10) + 'px';
            tooltip.style.top = (y - 30) + 'px';

            d3.select(this)
                .style('filter', 'brightness(1.15)')
                .style('stroke-width', '4px');
        })
        .on('mouseleave', function() {
            document.getElementById('tooltip').classList.remove('visible');
            d3.select(this)
                .style('filter', selectedTicker === d3.select(this).datum().ticker ? 'brightness(1.15)' : 'brightness(1)')
                .style('stroke-width', selectedTicker === d3.select(this).datum().ticker ? '4px' : '2px');
        })
        .on('click', function(event, d) {
            event.stopPropagation();
            selectStock(d.ticker);
        });

    // Update positions on simulation tick
    simulation.on('tick', () => {
        circles
            .attr('cx', d => d.x)
            .attr('cy', d => d.y);

        labels
            .attr('x', d => d.x)
            .attr('y', d => d.y);
    });

    // Create legend
    createLegend(sectors);
}

function createLegend(sectors) {
    const legendDiv = document.getElementById('legend');
    legendDiv.innerHTML = '';

    sectors.sort().forEach(sector => {
        const item = document.createElement('div');
        item.className = 'legend-item';

        const colorBox = document.createElement('div');
        colorBox.className = 'legend-color';
        colorBox.style.backgroundColor = sectorColors[sector] || sectorColors['Other'];

        const label = document.createElement('span');
        label.textContent = sector;

        item.appendChild(colorBox);
        item.appendChild(label);
        legendDiv.appendChild(item);
    });
}

function initTable() {
    const tbody = document.querySelector('#stocks-table tbody');
    tbody.innerHTML = '';

    // Sort stocks by ticker for consistent display
    const sortedData = [...stockData].sort((a, b) => a.ticker.localeCompare(b.ticker));

    sortedData.forEach(stock => {
        const row = document.createElement('tr');
        row.dataset.ticker = stock.ticker;

        // Format market cap
        let marketCapStr = '-';
        if (stock.marketCap > 0) {
            marketCapStr = formatMarketCap(stock.marketCap);
        }

        row.innerHTML = `
            <td>${stock.ticker}</td>
            <td>${stock.name}</td>
            <td>${stock.sector}</td>
            <td>${marketCapStr}</td>
        `;

        row.addEventListener('click', () => {
            selectStock(stock.ticker);
        });

        tbody.appendChild(row);
    });
}

function formatMarketCap(value) {
    if (value >= 1e12) {
        return (value / 1e12).toFixed(2) + 'T';
    } else if (value >= 1e9) {
        return (value / 1e9).toFixed(2) + 'B';
    } else if (value >= 1e6) {
        return (value / 1e6).toFixed(2) + 'M';
    }
    return value.toString();
}

function selectStock(ticker) {
    selectedTicker = selectedTicker === ticker ? null : ticker;

    // Update bubble highlighting
    d3.selectAll('.bubble').each(function(d) {
        const circle = d3.select(this);
        if (selectedTicker === d.ticker) {
            circle.attr('class', 'bubble highlighted');
        } else {
            circle.attr('class', 'bubble');
        }
    });

    // Update table highlighting
    document.querySelectorAll('#stocks-table tbody tr').forEach(row => {
        if (selectedTicker && row.dataset.ticker === selectedTicker) {
            row.classList.add('highlighted');
            row.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        } else {
            row.classList.remove('highlighted');
        }
    });
}

// Load data when DOM is ready
document.addEventListener('DOMContentLoaded', loadData);

