            <td>${stock.name}</td>
            <td>${stock.sector}</td>
            <td>${marketCapStr}</td>
        `;

        row.addEventListener('click', () => {
            selectStock(stock.ticker);
        });

        tbody.appendChild(row);
    });
}

function formatMarketCap(value) {
    if (value >= 1e12) {
        return (value / 1e12).toFixed(2) + 'T';
    } else if (value >= 1e9) {
        return (value / 1e9).toFixed(2) + 'B';
    } else if (value >= 1e6) {
        return (value / 1e6).toFixed(2) + 'M';
    }
    return value.toString();
}

function selectStock(ticker) {
    selectedTicker = selectedTicker === ticker ? null : ticker;

    // Update bubble highlighting
    d3.selectAll('.bubble').each(function(d) {
        const circle = d3.select(this);
        if (selectedTicker === d.ticker) {
            circle.attr('class', 'bubble highlighted');
        } else {
            circle.attr('class', 'bubble');
        }
    });

    // Update table highlighting
    document.querySelectorAll('#stocks-table tbody tr').forEach(row => {
        if (selectedTicker && row.dataset.ticker === selectedTicker) {
            row.classList.add('highlighted');
            row.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        } else {
            row.classList.remove('highlighted');
        }
    });
}

// Load data when DOM is ready
document.addEventListener('DOMContentLoaded', loadData);

